-- Generated by tools/gen_affinity.py, do not edit: one server-side passive per affinity (+100%% spell mod on the
-- boosted skill's family bits, modelled on the "Improved <skill>" talents) and the pool the module rolls from.

CREATE TABLE IF NOT EXISTS `affinity_pool` (
  `id` INT UNSIGNED NOT NULL COMMENT 'permanent, stored in character_affinity',
  `class` TINYINT UNSIGNED NOT NULL,
  `aura_id` INT UNSIGNED NOT NULL COMMENT 'spell_dbc passive applied to the character',
  `spell_id` INT UNSIGNED NOT NULL COMMENT 'boosted skill, rank 1: eligibility, icon, link',
  `extra_spells` VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'other skills covered by the same bits',
  `text` VARCHAR(100) NOT NULL,
  `weight` INT UNSIGNED NOT NULL DEFAULT 100 COMMENT 'relative roll chance, 0 removes the entry from the roll',
  `comment` VARCHAR(150) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE `class` = VALUES(`class`), `aura_id` = VALUES(`aura_id`), `spell_id` = VALUES(`spell_id`), `extra_spells` = VALUES(`extra_spells`), `text` = VALUES(`text`), `comment` = VALUES(`comment`);

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 250001 AND 250129;
